export const listStockHistoryQueryDateFromRegExp = new RegExp('^[0-9]{4}-[0-9]{2}-[0-9]{2}$');
export const listStockHistoryQueryDateToRegExp = new RegExp('^[0-9]{4}-[0-9]{2}-[0-9]{2}$');


